// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the bricks and the paddle. Brick collision lives here (not in
// the render loop): the sweep needs the position BEFORE the step, which only
// `step()` knows.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const x0 = ball.x;
  const y0 = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Bricks: swept collision, one bounce per pass. Any contact breaks the
  // brick and scores; only the first contact of the pass deflects the ball,
  // so a seam overlapping two bricks cannot cancel two inversions.
  let bounced = false;
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    const contact = sweptContact(ball, x0, y0, ball.x, ball.y, brick);
    if (!contact) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);

    if (bounced) continue;
    const face = contact.inside ? penetrationFace(ball, brick) : contact.face;
    if (!isApproaching(ball, face)) continue; // separating graze: break, don't bounce
    bounceOff(ball, brick, face);
    bounced = true;
  }

  // Paddle — swept band test: the bottom-edge segment vs the paddle band, so
  // a fast ball cannot jump over the paddle in a single frame.
  if (
    ball.vy > 0 &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w &&
    Math.max(y0 + ball.r, ball.y + ball.r) >= paddle.y &&
    Math.min(y0 + ball.r, ball.y + ball.r) <= paddle.y + paddle.h
  ) {
    ball.y = paddle.y - ball.r;
    state.combo = 0; // touching the paddle resets the combo
    // The rebound direction follows the paddle hit, with a minimum angle so
    // a dead-center touch never launches a purely vertical trajectory.
    let hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    hit = Math.max(-1, Math.min(1, hit));
    if (Math.abs(hit) < MIN_PADDLE_HIT) {
      hit = hit < 0 ? -MIN_PADDLE_HIT : MIN_PADDLE_HIT;
    }
    // Renormalize so the bounce keeps exactly the level's speed.
    const norm = Math.hypot(hit, 1);
    const speed = ballSpeed(state.level);
    ball.vx = (speed * hit) / norm;
    ball.vy = -speed / norm;
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

