// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The sweep below (`sweptContact`) is the actual game
// detector; `collides` stays as the documented primitive.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Minimum |hit| at the paddle: a dead-center touch must never produce a
// purely vertical trajectory (angle mort).
const MIN_PADDLE_HIT = 0.3;

// Swept circle-vs-AABB contact (slab method, GameDev.net Swept AABB). Sweeps
// the ball's center segment (x0,y0) -> (x1,y1) against the brick expanded by
// the ball radius, i.e. the zone the circle physically touches.
// Returns null when the segment never touches the zone, `{ inside: true }`
// when it starts inside it (recouvrement already present), or the face the
// segment crosses (`top` | `bottom` | `left` | `right` | `corner`) when it
// enters the zone from outside — which is how a fast ball cannot jump over a
// brick in one frame.
function sweptContact(ball, x0, y0, x1, y1, brick) {
  const r = ball.r;
  const ex = brick.x - r;
  const ey = brick.y - r;
  const ew = brick.w + 2 * r;
  const eh = brick.h + 2 * r;
  const dx = x1 - x0;
  const dy = y1 - y0;

  // Entry/exit time of the segment on one axis (the slab method).
  const slab = (a0, d, lo, hi) => {
    if (Math.abs(d) < 1e-12) {
      if (a0 < lo || a0 > hi) return null; // parallel and outside
      return { entry: -Infinity, exit: Infinity };
    }
    const t1 = (lo - a0) / d;
    const t2 = (hi - a0) / d;
    return { entry: Math.min(t1, t2), exit: Math.max(t1, t2), dir: Math.sign(d) };
  };

  const tx = slab(x0, dx, ex, ex + ew);
  const ty = slab(y0, dy, ey, ey + eh);
  if (!tx || !ty) return null;

  const entry = Math.max(tx.entry, ty.entry);
  const exit = Math.min(tx.exit, ty.exit);
  if (entry > exit || exit < 0 || entry > 1) return null;
  if (entry < 0) return { inside: true };

  // The face crossed is the axis that entered LAST (GameDev.net: the largest
  // entry time), oriented by the travel direction.
  if (ty.entry > tx.entry) return { face: dy > 0 ? 'top' : 'bottom' };
  if (tx.entry > ty.entry) return { face: dx > 0 ? 'left' : 'right' };
  return { face: 'corner' };
}

// Face hit when the ball already overlaps the brick: the axis of the smallest
// penetration. Equal penetrations mean a corner: both axes are inverted.
function penetrationFace(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  if (Math.abs(penX - penY) < 1e-9) return 'corner';
  if (penX < penY) return penLeft <= penRight ? 'left' : 'right';
  return penTop <= penBottom ? 'top' : 'bottom';
}

// True when the velocity drives the ball INTO the face (a separating graze
// must not bounce — it would be a ghost collision).
function isApproaching(ball, face) {
  switch (face) {
    case 'left': return ball.vx > 0;
    case 'right': return ball.vx < 0;
    case 'top': return ball.vy > 0;
    case 'bottom': return ball.vy < 0;
    default: return true; // corner
  }
}

// Inverts the velocity on the touched axis and pushes the ball back out of
// the brick, at most touching the face (no more recouvrement).
function bounceOff(ball, brick, face) {
  switch (face) {
    case 'left':
      ball.vx = -Math.abs(ball.vx);
      ball.x = brick.x - ball.r;
      break;
    case 'right':
      ball.vx = Math.abs(ball.vx);
      ball.x = brick.x + brick.w + ball.r;
      break;
    case 'top':
      ball.vy = -Math.abs(ball.vy);
      ball.y = brick.y - ball.r;
      break;
    case 'bottom':
      ball.vy = Math.abs(ball.vy);
      ball.y = brick.y + brick.h + ball.r;
      break;
    case 'corner':
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
      ball.x = ball.x < brick.x ? brick.x - ball.r : brick.x + brick.w + ball.r;
      ball.y = ball.y < brick.y ? brick.y - ball.r : brick.y + brick.h + ball.r;
      break;
  }
}

